srcDoc.js:
function val(value) {
  return String(value ?? "");
}
function money(value) {
  return Number(value || 0).toFixed(2);
}
function qty(value) {
  return Number(value || 0).toFixed(4);
}
function initials(name) {
  return val(name || "AX").split(" ").filter(Boolean).slice(0, 2).map(x => x[0]).join("").toUpperCase();
}
function qrPayload(h) {
  return ["TYPE=PURCHASE_RETURN", "NUMBER=" + val(h.documentNumber), "DATE=" + val(h.documentDate), "SUPPLIER=" + val(h.supplierName), "WAREHOUSE=" + val(h.warehouseCode), "TOTAL=" + val(h.totalAmount)].join("&");
}
function render(model) {
  const h = model.header || {};
  const items = model.items || [];
  const companyDisplay = h.companyLegalName || h.companyName || "";
  document.getElementById("companyName").innerText = companyDisplay || "Company";
  document.getElementById("companyMeta").innerText = [h.companyAddressLine1 || h.companyAddress, h.companyPostalCode, h.companyCity, h.companyTaxNumber ? "Tax No: " + h.companyTaxNumber : "", h.companyEmail, h.companyPhone].filter(Boolean).join(" | ");
  const logo = document.getElementById("logo");
  const fallback = document.getElementById("logoFallback");
  if (h.companyLogoPath || h.company_logo_path) {
    logo.src = h.companyLogoPath || h.company_logo_path;
    logo.style.display = "block";
    fallback.style.display = "none";
  } else {
    logo.style.display = "flex";
    fallback.innerText = initials(companyDisplay);
  }
  document.getElementById("documentNumber").innerText = h.documentNumber || "";
  document.getElementById("status").innerText = h.status || "";
  document.getElementById("documentDate").innerText = h.documentDate || "";
  document.getElementById("sourceNumber").innerText = h.sourceDocumentNumber || "-";
  document.getElementById("warehouse").innerText = `${h.warehouseCode || ""} - ${h.warehouseName || ""}`;
  document.getElementById("createdBy").innerText = model.username || h.createdBy || "";
  document.getElementById("supplierName").innerText = `${h.supplierCode || ""} ${h.supplierName || ""}`.trim() || "-";
  document.getElementById("supplierDetails").innerText = [h.supplierTaxNumber ? "Tax No: " + h.supplierTaxNumber : "", h.supplierAddressLine1, h.supplierPostalCode, h.supplierCity, h.supplierEmail, h.supplierPhone].filter(Boolean).join(" | ") || "-";
  document.getElementById("reason").innerText = h.reason || "RETURN TO SUPPLIER";
  document.getElementById("note").innerText = h.note || "-";
  let totalQty = 0;
  let totalValue = 0;
  document.getElementById("itemsBody").innerHTML = items.map((row, index) => {
    const rowQty = Number(row.quantity || row.returnQuantity || 0);
    const rowTotal = Number(row.lineTotal || 0);
    totalQty += rowQty;
    totalValue += rowTotal;
    return `
      <tr>
        <td>${val(row.lineNo || index + 1)}</td>
        <td>
          <div class="product-code">${val(row.productCode)}</div>
          <div class="product-name">${val(row.productName)}${row.barcode ? " | " + val(row.barcode) : ""}</div>
        </td>
        <td>${val(row.description || row.productName)}</td>
        <td class="right">${qty(rowQty)}</td>
        <td>${val(row.unitCode)}</td>
        <td class="right">${money(row.unitCost)}</td>
        <td class="right">${money(rowTotal)}</td>
      </tr>
    `;
  }).join("");
  document.getElementById("itemCount").innerText = `${items.length} line${items.length === 1 ? "" : "s"}`;
  document.getElementById("totalQty").innerText = qty(totalQty);
  document.getElementById("totalValue").innerText = money(totalValue);
  const qrUrl = "https://api.qrserver.com/v1/create-qr-code/?size=140x140&ecc=M&margin=1&data=" + encodeURIComponent(qrPayload(h));
  document.getElementById("qr").src = qrUrl;
  document.getElementById("qrText").innerText = h.documentNumber || "";
  document.getElementById("printBtn").onclick = () => window.print();
}
appsmith.onReady(() => {
  render(appsmith.model || {});
});
appsmith.onModelChange(model => {
  render(model || {});
});

